steps.script:
set -euo pipefail
[ "${app_dir}" != '<app_dir>' ] || { echo '缺少参数 app_dir（例如 /root/myapp 或 /opt/app）' >&2; exit 2; }
[ -d "${app_dir}" ] || { echo "目录不存在 ${app_dir}" >&2; exit 3; }
[ -f "${app_dir}/${compose_file}" ] || { echo "编排文件不存在 ${app_dir}/${compose_file}" >&2; exit 4; }
echo "compose-dir-ok ${app_dir}/${compose_file}"
